{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "First, the physical activity used to meet that requirement must include unstructured play outside. The exception is when weather conditions negatively impact reasonable execution of physical activity outside.",
      "rationale": "Conveys the required unstructured outdoor play and the weather exception for qualifying physical activity."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The activity could not count time when a student is allowed to use an electronic device.",
      "rationale": "Conveys that time when electronic-device use is permitted does not count toward the physical activity requirement."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "It also could not count time a student spends in a physical education class.",
      "rationale": "Conveys the exclusion of physical education class time from qualifying physical activity."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Second, a student could be denied the privilege of taking part in physical activity. This could happen if the student breaks the school or school district discipline policy or code of conduct. It could also happen if the student acts in a violent or threatening way, or in another way that significantly disrupts or impairs other students' ability to take part in the activity and get its benefits.\n\nThird, a teacher or administrator could use this as discipline. The teacher or administrator may remove a student from, or deny participation in, any physical activity or activity period for that conduct.",
      "rationale": "Identifies the authorized actors, removal or denial as discipline, and all specified grounds, including the significant-disruption threshold."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "The teacher or administrator may also give a removed student alternative lessons, assignments, or activities, including physical activities, to improve the student's conduct or behavior.",
      "rationale": "Conveys the actors, alternative assignments, and behavioral purpose, but mentions only removed students, omitting students denied participation."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The bill would take effect as soon as it becomes law.",
      "rationale": "Accurately conveys the effective date."
    }
  ]
}
